import { useCallback, useEffect, useState } from 'react';
import {
  FlatList,
  Text,
  View,
  ActivityIndicator,
  RefreshControl,
  StyleSheet,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

interface FeedItem {
  id: string;
  title: string;
}

const PAGE_SIZE = 20;

async function fetchPage(page: number): Promise<FeedItem[]> {
  const response = await fetch(`https://api.example.com/feed?page=${page}&size=${PAGE_SIZE}`);
  if (!response.ok) throw new Error(`Request failed: ${response.status}`);
  return (await response.json()) as FeedItem[];
}

export function FeedScreen(): JSX.Element {
  const [items, setItems] = useState<FeedItem[]>([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async (nextPage: number, replace: boolean) => {
    try {
      const pageItems = await fetchPage(nextPage);
      setItems(prev => (replace ? pageItems : [...prev, ...pageItems]));
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load feed');
    }
  }, []);

  useEffect(() => {
    load(1, true).finally(() => setLoading(false));
  }, [load]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await load(1, true);
    setPage(1);
    setRefreshing(false);
  }, [load]);

  const onEndReached = useCallback(async () => {
    const next = page + 1;
    await load(next, false);
    setPage(next);
  }, [load, page]);

  if (loading) {
    return <View style={styles.center}><ActivityIndicator testID="loading" /></View>;
  }
  if (error !== null && items.length === 0) {
    return (
      <View style={styles.center}>
        <Text style={styles.error}>{error}</Text>
      </View>
    );
  }
  return (
    <SafeAreaView style={styles.safe}>
      <FlatList
        data={items}
        keyExtractor={item => item.id}
        renderItem={({ item }) => <Text style={styles.row}>{item.title}</Text>}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
        }
        onEndReached={onEndReached}
        onEndReachedThreshold={0.5}
        ListEmptyComponent={<Text>No feed items yet.</Text>}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  center: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: 24 },
  row: { padding: 16, fontSize: 16 },
  error: { color: '#FF3B30' },
});
